    private String notice="", pendingExport="", exportText="", appSearch="", logSearch="", busyLabel="";
    private boolean statusLoaded=false, homeRefreshNeeded=false;
    private String bundledModuleVersion="";
    private String queuedDocumentUri="", queuedDocumentKind="", queuedDocumentText="";
    private int queuedDocumentRequest=0;
    private final SharedPreferences.OnSharedPreferenceChangeListener preferenceListener=(p,key)->{
        if("dnsNetworkState".equals(key)||"dnsNetworkReportError".equals(key)||"dailyUpdateRunning".equals(key)||"dailyUpdateError".equals(key)||"dailyUpdateLastSuccess".equals(key)||"dnsLogs".equals(key)||"activeBypassApps".equals(key)||"vpnError".equals(key)||"vpnWanted".equals(key)||"blocked".equals(key)||"queries".equals(key)||"errors".equals(key)) {
            if(!"dnsLogs".equals(key))homeRefreshNeeded=true;
            ui.removeCallbacks(this.refreshLive); ui.postDelayed(this.refreshLive,180);
        }
    };
    private final Runnable refreshLive=()->{
        if(destroyed)return;
        if(homeRefreshNeeded&&tab==0)showPage(true);homeRefreshNeeded=false;
        if(tab==1)updatePending();
        if(tab==3&&logAdapter!=null){logAdapter.refresh();if(queryMetric!=null)queryMetric.setText(format(prefs.getLong("queries",0)));if(blockMetric!=null)blockMetric.setText(format(prefs.getLong("blocked",0)));if(errorMetric!=null)errorMetric.setText(format(prefs.getLong("errors",0)));}
    };
    private interface Job { String run() throws Exception; }
    private interface Flag { void changed(boolean on); }
    private static final class AppEntry {
        final ApplicationInfo info; final String label; final Bitmap icon;
        AppEntry(ApplicationInfo i,String l,Bitmap b){info=i;label=l;icon=b;}
    }
    @Override public void onCreate(Bundle state) {
        prefs=getSharedPreferences("bichen",MODE_PRIVATE);
        dark=useDark();setTheme(dark?R.style.AppThemeDark:R.style.AppTheme);
        super.onCreate(state); palette();
        if(state!=null){tab=state.getInt("tab",0);appSearch=state.getString("appSearch","");logSearch=state.getString("logSearch","");systemApps=state.getBoolean("systemApps");selectedOnly=state.getBoolean("selectedOnly");pendingExport=state.getString("pendingExport","");exportText=state.getString("exportText","");queuedDocumentUri=state.getString("queuedDocumentUri","");queuedDocumentKind=state.getString("queuedDocumentKind","");queuedDocumentText=state.getString("queuedDocumentText","");queuedDocumentRequest=state.getInt("queuedDocumentRequest",0);}
        buildWindow();showPage(false);prefs.registerOnSharedPreferenceChangeListener(preferenceListener);
        loadStatus();
    }
    @Override public void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);b.putInt("tab",tab);b.putString("appSearch",appSearch);b.putString("logSearch",logSearch);b.putBoolean("systemApps",systemApps);b.putBoolean("selectedOnly",selectedOnly);b.putString("pendingExport",pendingExport);b.putString("exportText",exportText);b.putString("queuedDocumentUri",queuedDocumentUri);b.putString("queuedDocumentKind",queuedDocumentKind);b.putString("queuedDocumentText",queuedDocumentText);b.putInt("queuedDocumentRequest",queuedDocumentRequest);}
    @Override public void onResume(){super.onResume();if(prefs!=null){if(useDark()!=dark){recreate();return;}String e=prefs.getString("vpnError","");if(!e.isEmpty()){notice=e;updateBanner();}ui.post(refreshLive);}}
    @Override public void onDestroy(){destroyed=true;prefs.unregisterOnSharedPreferenceChangeListener(preferenceListener);ui.removeCallbacksAndMessages(null);worker.shutdown();super.onDestroy();}
    private boolean useDark(){String mode=prefs.getString("appearance","system");return mode.equals("dark")||(mode.equals("system")&&(getResources().getConfiguration().uiMode&Configuration.UI_MODE_NIGHT_MASK)==Configuration.UI_MODE_NIGHT_YES);}
    private void palette(){BG=dark?0xff121714:0xfff4f5f2;TEXT=dark?0xffe6eee8:0xff22342b;MUTED=dark?0xff9aa99f:0xff78867d;ACCENT=dark?0xff8dd3c3:0xff317c70;SURFACE=dark?0xff1d2721:0xfffefefd;SOFT=dark?0xff283930:0xffe8efea;LINE=dark?0xff324036:0xffe9eeea;ERROR=dark?0xffffb6a0:0xffac5d45;}
    private int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}
    private GradientDrawable background(int color,float radius){GradientDrawable g=new GradientDrawable();g.setColor(color);g.setCornerRadius(dp(radius));return g;}
    private Drawable tappable(int color,float radius){return new RippleDrawable(ColorStateList.valueOf(dark?0x228dd3c3:0x18317c70),background(color,radius),background(Color.WHITE,radius));}
    private LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
    private LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
    private TextView text(String s,float size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setFontFeatureSettings("kern");t.setIncludeFontPadding(false);t.setLineSpacing(dp(3),1);if(bold)t.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));return t;}
    private void gap(LinearLayout l,int height){l.addView(new View(this),new LinearLayout.LayoutParams(1,dp(height)));}
    private void pad(View v,int n){v.setPadding(dp(n),dp(n),dp(n),dp(n));}
    private void divider(LinearLayout l){View line=new View(this);line.setBackgroundColor(LINE);l.addView(line,new LinearLayout.LayoutParams(-1,dp(1)));}
    private void action(Runnable r){if(busy){Toast.makeText(this,busyLabel+"，请稍候",Toast.LENGTH_SHORT).show();return;}r.run();}
    private TextView button(String label,boolean primary,Runnable runnable){TextView t=text(label,14,primary?(dark?0xff163b31:Color.WHITE):ACCENT,true);t.setGravity(Gravity.CENTER);t.setPadding(dp(15),dp(14),dp(15),dp(14));t.setMinHeight(dp(48));t.setBackground(tappable(primary?ACCENT:SOFT,17));t.setOnClickListener(v->action(runnable));return t;}
    private void addButton(LinearLayout l,String label,boolean primary,Runnable runnable){gap(l,12);l.addView(button(label,primary,runnable),new LinearLayout.LayoutParams(-1,-2));}
    private View iconButton(String icon,String description,Runnable click){FrameLayout f=new FrameLayout(this);f.setBackground(tappable(SURFACE,23));f.setElevation(dp(1));IconView i=new IconView(this,icon,TEXT);FrameLayout.LayoutParams ip=new FrameLayout.LayoutParams(dp(21),dp(21),Gravity.CENTER);f.addView(i,ip);f.setContentDescription(description);f.setOnClickListener(v->action(click));f.setLayoutParams(new LinearLayout.LayoutParams(dp(44),dp(44)));return f;}
    private LinearLayout card(LinearLayout parent){LinearLayout c=column();pad(c,20);GradientDrawable g=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{SURFACE,dark?0xff202c24:0xfffafcf9});g.setCornerRadius(dp(24));c.setBackground(g);c.setElevation(dp(dark?0:1.4f));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(14);parent.addView(c,p);return c;}
    private LinearLayout card(String title,String description){LinearLayout c=card(body);if(title!=null)c.addView(text(title,17,TEXT,true));if(description!=null){gap(c,8);c.addView(text(description,12,MUTED,false));}return c;}
    private void section(String title){TextView t=text(title,13,MUTED,true);t.setPadding(dp(5),dp(5),0,dp(12));body.addView(t);}
    private LinearLayout actionRow(LinearLayout parent,String icon,String title,String description,Runnable runnable){LinearLayout r=row();r.setPadding(0,dp(13),0,dp(13));r.setMinimumHeight(dp(58));r.setBackground(tappable(Color.TRANSPARENT,12));IconView i=new IconView(this,icon,ACCENT);r.addView(i,new LinearLayout.LayoutParams(dp(23),dp(23)));LinearLayout labels=column();labels.setPadding(dp(13),0,dp(9),0);labels.addView(text(title,14,TEXT,true));if(description!=null&&!description.isEmpty()){gap(labels,5);labels.addView(text(description,11,MUTED,false));}r.addView(labels,new LinearLayout.LayoutParams(0,-2,1));r.addView(new IconView(this,"chevron",MUTED),new LinearLayout.LayoutParams(dp(16),dp(16)));r.setOnClickListener(v->action(runnable));parent.addView(r,new LinearLayout.LayoutParams(-1,-2));return r;}
    private void buildWindow(){
        shell=column();shell.setBackgroundColor(BG);shell.setClipChildren(false);
        shell.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets.consumeSystemWindowInsets();});
        getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);
        getWindow().getDecorView().setSystemUiVisibility(dark?0:View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);
        LinearLayout header=row();header.setPadding(dp(23),dp(17),dp(21),dp(17));LinearLayout labels=column();heading=text("辟尘",29,TEXT,true);labels.addView(heading);gap(labels,7);subtitle=text("少一点打扰，多一点清净",12,MUTED,false);labels.addView(subtitle);header.addView(labels,new LinearLayout.LayoutParams(0,-2,1));header.addView(iconButton("settings","设置与诊断",this::showSettings));shell.addView(header);
        progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setIndeterminate(true);progress.setIndeterminateTintList(ColorStateList.valueOf(ACCENT));progress.setVisibility(View.GONE);shell.addView(progress,new LinearLayout.LayoutParams(-1,dp(3)));
        banner=row();banner.setPadding(dp(15),dp(11),dp(8),dp(11));banner.setBackground(background(SOFT,17));feedback=text("",12,ACCENT,false);feedback.setMaxLines(3);feedback.setEllipsize(TextUtils.TruncateAt.END);feedback.setOnClickListener(v->showLong("操作结果",notice));banner.addView(feedback,new LinearLayout.LayoutParams(0,-2,1));TextView close=text("×",23,MUTED,false);close.setGravity(Gravity.CENTER);close.setContentDescription("收起提示");close.setOnClickListener(v->{notice="";updateBanner();});banner.addView(close,new LinearLayout.LayoutParams(dp(36),dp(36)));LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,-2);bp.setMargins(dp(19),0,dp(19),dp(12));shell.addView(banner,bp);
        content=new FrameLayout(this);shell.addView(content,new LinearLayout.LayoutParams(-1,0,1));
        nav=row();nav.setPadding(dp(7),dp(6),dp(7),dp(6));nav.setBackground(new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,new int[]{dark?0xff2b3830:0xfffefffd,dark?0xff1e2922:0xffedf3ed}));nav.getBackground().setAlpha(245);((GradientDrawable)nav.getBackground()).setCornerRadius(dp(29));nav.setElevation(dp(8));LinearLayout.LayoutParams np=new LinearLayout.LayoutParams(-1,dp(70));np.setMargins(dp(24),dp(8),dp(24),dp(12));shell.addView(nav,np);
        setContentView(shell);updateBanner();renderNav();
    }
    private void renderNav(){nav.removeAllViews();String[] labels={"保护","应用","规则","活动"},icons={"shield","apps","rules","activity"};for(int n=0;n<4;n++){final int selected=n;LinearLayout item=column();item.setGravity(Gravity.CENTER);item.setBackground(tappable(n==tab?SOFT:Color.TRANSPARENT,22));item.addView(new IconView(this,icons[n],n==tab?ACCENT:MUTED),new LinearLayout.LayoutParams(dp(22),dp(22)));gap(item,5);item.addView(text(labels[n],11,n==tab?ACCENT:MUTED,n==tab));item.setContentDescription(labels[n]);item.setSelected(n==tab);item.setOnClickListener(v->{if(tab==selected)return;((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(content.getWindowToken(),0);tab=selected;showPage(false);renderNav();});nav.addView(item,new LinearLayout.LayoutParams(0,-1,1));}}
    private void showPage(boolean preserve){if(destroyed)return;int oldY=preserve&&scroll!=null?scroll.getScrollY():0;content.removeAllViews();scroll=null;appAdapter=null;logAdapter=null;logList=null;appsPending=null;appsApply=null;heading.setText(new String[]{"辟尘","应用放行","过滤规则","请求活动"}[tab]);subtitle.setText(new String[]{"少一点打扰，多一点清净","把选择权交还给你","来源、例外与每一次变化","保护发生了什么，一眼看清"}[tab]);
        if(tab==1){applicationPage();return;}if(tab==3){activityPage();return;}
        scroll=new ScrollView(this);scroll.setClipToPadding(false);scroll.setFillViewport(true);scroll.setVerticalScrollBarEnabled(false);body=column();body.setPadding(dp(19),dp(3),dp(19),dp(10));scroll.addView(body);content.addView(scroll,new FrameLayout.LayoutParams(-1,-1));if(tab==0)home();else rulePage();if(preserve){ScrollView s=scroll;s.post(()->s.scrollTo(0,oldY));}
    }
    private void updateBanner(){if(feedback==null)return;progress.setVisibility(busy?View.VISIBLE:View.GONE);banner.setVisibility(notice.isEmpty()&&!busy?View.GONE:View.VISIBLE);feedback.setText(busy?busyLabel+"…":notice);}
    private boolean installed(){return status.optBoolean("installed",false);}
    private boolean modern(){return status.optString("capabilities").contains("export-domains");}
    private boolean vpn(){return DnsVpnService.running;}
    private boolean vpnEngaged(){return vpn()||prefs.getBoolean("vpnWanted",false)||prefs.getBoolean("vpnRestoreHosts",false);}
    private boolean protectedNow(){return vpn()||(status.optBoolean("enabled")&&status.optBoolean("mounted"));}
    private String mode(){return vpnEngaged()?"vpn":prefs.getString("preferredMode","module");}
    private boolean ruleTarget()throws IOException{if(pendingReboot())throw new IOException("模块更新等待重启，请先重启手机。");if(!status.optBoolean("ok",false)||!status.has("installed"))throw new IOException("尚未确认模块状态，请刷新并完成 Root 授权。");if(installed()&&!modern())throw new IOException("请先安装内置新版模块并重启，再修改规则。");return installed();}
    private void home(){
        boolean active=protectedNow();LinearLayout hero=card(body);hero.setPadding(dp(23),dp(25),dp(23),dp(24));GradientDrawable g=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{dark?0xff233f34:0xffdeeee3,dark?0xff1f3128:0xfff5f3e6});g.setCornerRadius(dp(28));hero.setBackground(g);
        LinearLayout top=row();TextView eyebrow=text(active?"正在守护":"你的数字生活",12,ACCENT,true);top.addView(eyebrow,new LinearLayout.LayoutParams(0,-2,1));TextView modeChip=text(mode().equals("vpn")?"应用保护":"模块保护",11,ACCENT,true);modeChip.setPadding(dp(11),dp(7),dp(11),dp(7));modeChip.setBackground(tappable(dark?0xff354e40:0xfff6faf5,18));modeChip.setOnClickListener(v->action(this::showModePicker));top.addView(modeChip);hero.addView(top);gap(hero,22);
        LinearLayout state=row();LinearLayout name=column();name.addView(text(active?"保护已开启":vpnEngaged()?"保护正在切换":statusLoaded?"保护未开启":"正在检查状态",27,TEXT,true));gap(name,10);String detail=vpn()?networkSummary()+" · "+prefs.getInt("activeBypassCount",0)+" 个应用放行":active?"系统 hosts 已验证生效":!statusLoaded?"请完成 Root 授权，稍候查看结果":installed()?(status.optBoolean("enabled")?"规则已启用，实际挂载尚未验证":"随时开启，恢复清净日常"):"安装内置模块，开启系统保护";TextView desc=text(detail,12,MUTED,false);name.addView(desc);state.addView(name,new LinearLayout.LayoutParams(0,-2,1));FrameLayout power=new FrameLayout(this);power.setBackground(tappable(active?ACCENT:SURFACE,32));power.setElevation(dp(4));power.addView(new IconView(this,"power",active?(dark?0xff163b31:Color.WHITE):ACCENT),new FrameLayout.LayoutParams(dp(29),dp(29),Gravity.CENTER));power.setContentDescription(active?"停止保护":"开启保护");power.setOnClickListener(v->action(this::toggleProtection));LinearLayout.LayoutParams pp=new LinearLayout.LayoutParams(dp(64),dp(64));pp.leftMargin=dp(12);state.addView(power,pp);hero.addView(state);gap(hero,27);
        divider(hero);gap(hero,20);LinearLayout metrics=row();metric(metrics,format(rules==null?0:vpn()?rules.count():status.optInt("ruleCount")),"有效过滤规则");metric(metrics,vpn()?format(prefs.getLong("blocked",0)):bytes(status.optLong("hostsBytes")),vpn()?"累计 DNS 拦截":"规则文件大小");hero.addView(metrics);
        if(status.has("error")||!status.optBoolean("ok",true)){LinearLayout warning=card("需要处理",status.optString("error",status.optString("message","模块状态检查未成功")));actionRow(warning,"refresh","重新检查","完成 Root 授权后再试",this::loadStatus);}
        section("保护概览");LinearLayout overview=card(null,null);actionRow(overview,"module",installed()?"模块已安装 · "+status.optString("version","未知版本"):"安装辟尘模块",installed()?(status.optBoolean("mounted")?"挂载已验证 · ":"挂载未验证 · ")+bytes(status.optLong("storageBytes"))+" 数据占用":"App 已内置安装包，无需另外下载",this::showModuleManager);divider(overview);actionRow(overview,"rules","规则与更新",updateSummary(),()->{tab=2;showPage(false);renderNav();});divider(overview);actionRow(overview,"search","遇到误拦？","检查域名，或从请求记录一键放行",this::showTroubleshooter);
        LinearLayout hint=card(null,null);hint.addView(text(vpn()?"应用保护使用系统 VPN 槽位。打开其他 VPN 前，请先停止辟尘应用保护。":"模块保护不占 VPN，按域名拦截广告与追踪。需要按应用放行时，可切换到应用保护。",12,MUTED,false));actionRow(hint,"shield","切换保护方式",mode().equals("vpn")?"当前选择：应用保护":"当前选择：模块保护",this::showModePicker);
    }
    private TextView metric(LinearLayout p,String value,String label){LinearLayout c=column();TextView number=text(value,23,TEXT,true);c.addView(number);gap(c,7);c.addView(text(label,11,MUTED,false));p.addView(c,new LinearLayout.LayoutParams(0,-2,1));return number;}
    private String updateSummary(){if(prefs.getBoolean("dailyUpdateRunning",false))return "规则正在后台更新";String error=prefs.getString("dailyUpdateError","");if(!error.isEmpty())return "自动更新遇到问题，点此查看";long t=prefs.getLong("dailyUpdateLastSuccess",0);if(t==0)t=status.optLong("updatedAt",0)*1000;long checked=prefs.getLong("last_rule_check",0);if(checked>0)return "最近检查 "+date(checked)+" · 无变化时保留原规则";return t>0?"最近更新 "+date(t):"内置规则可离线使用";}
    private void toggleProtection(){if(vpnEngaged()){stopVpn();return;}if(protectedNow()){rootCommand("pause");return;}if(mode().equals("vpn"))prepareVpn();else if(!installed())showModuleManager();else rootCommand("enable");}
    private void showModePicker(){LinearLayout c=column();c.addView(text("选择保护方式",22,TEXT,true));gap(c,10);c.addView(text("两种方式互斥。应用保护支持单独放行，但会使用系统 VPN 槽位。",13,MUTED,false));final Dialog d=sheet(c);actionRow(c,"module","模块保护","不占 VPN · 所有应用共用域名规则",()->{d.dismiss();if(vpnEngaged()){new AlertDialog.Builder(this).setTitle("切回模块保护？").setMessage("将先停止应用保护并恢复原模块状态；恢复完成后可开启模块保护。").setNegativeButton("取消",null).setPositiveButton("切换",(a,b)->{prefs.edit().putString("preferredMode","module").apply();stopVpn();}).show();}else{prefs.edit().putString("preferredMode","module").apply();showPage(true);}});divider(c);actionRow(c,"apps","应用保护","本地 DNS VPN · 支持按应用放行",()->{d.dismiss();prepareVpn();});}
    private String networkSummary(){
        if(!vpn())return "应用保护未运行";
        String state=prefs.getString("dnsNetworkState","waiting");
        if("ready".equals(state))return "上游网络已连接，DNS 引擎运行中";
        if("blocked".equals(state))return "系统限制上游联网，保留本地过滤";
        return "等待网络恢复，保留本地过滤";
    }
    private void showModuleManager(){LinearLayout c=column();c.addView(text("模块管理",22,TEXT,true));gap(c,10);c.addView(text("App 版本："+version()+"\n内置模块："+(bundledModuleVersion.isEmpty()?"等待校验":bundledModuleVersion)+"\n安装 APK 是安装管理界面；Root 模块只从下方安装或导出。源码包不能刷入。",13,MUTED,false));final Dialog d=sheet(c);addButton(c,installed()?"安装内置模块更新":"安装内置模块",true,()->{d.dismiss();work("安装模块",()->{RootBridge.Result r=ModuleInstaller.install(this);if(r.code!=0)throw new IOException("安装失败（"+r.code+"）：\n"+r.output);return r.output;},this::loadStatus);});actionRow(c,"download","导出模块 ZIP","只导出已校验的模块，不含源码或 APK",()->{d.dismiss();exportFile("module");});divider(c);actionRow(c,"refresh","重新应用当前规则","修复当前模块挂载",()->{d.dismiss();rootCommand("apply");});divider(c);actionRow(c,"info","检查安装与挂载","查看真实诊断结果",()->{d.dismiss();runDiagnostics();});}
    private void applicationPage(){LinearLayout page=column();page.setPadding(dp(19),dp(3),dp(19),0);content.addView(page,new FrameLayout.LayoutParams(-1,-1));LinearLayout intro=card(page);intro.setPadding(dp(17),dp(15),dp(17),dp(15));LinearLayout top=row();LinearLayout labels=column();labels.addView(text("选中的应用直接放行",16,TEXT,true));gap(labels,7);appsPending=text("",12,MUTED,false);labels.addView(appsPending);top.addView(labels,new LinearLayout.LayoutParams(0,-2,1));appsApply=button(vpn()?"应用更改":"开启保护",true,()->{if(vpn())restartVpn();else prepareVpn();});LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(-2,-2);ap.leftMargin=dp(10);top.addView(appsApply,ap);intro.addView(top);gap(intro,10);intro.addView(text("仅应用保护生效；会占用 VPN。勾选后需点击应用更改。",11,MUTED,false));
        EditText search=input("搜索名称或包名");search.setText(appSearch);page.addView(search);watch(search,s->{appSearch=s;if(appAdapter!=null)appAdapter.filter();});
        LinearLayout filter=row();CheckBox sys=check("系统应用",systemApps);sys.setOnCheckedChangeListener((b,on)->{systemApps=on;appAdapter.filter();});filter.addView(sys,new LinearLayout.LayoutParams(0,dp(43),1));CheckBox selected=check("只看已选择",selectedOnly);selected.setOnCheckedChangeListener((b,on)->{selectedOnly=on;appAdapter.filter();});filter.addView(selected,new LinearLayout.LayoutParams(0,dp(43),1));page.addView(filter);
        ListView list=new ListView(this);list.setDivider(new ColorDrawable(LINE));list.setDividerHeight(dp(1));list.setClipToPadding(false);list.setPadding(dp(13),0,dp(9),dp(5));list.setBackground(background(SURFACE,22));list.setVerticalScrollBarEnabled(false);appEmpty=emptyView(page,"正在读取应用…");list.setEmptyView(appEmpty);appAdapter=new AppAdapter();list.setAdapter(appAdapter);page.addView(list,new LinearLayout.LayoutParams(-1,0,1));appAdapter.filter();updatePending();if(!appsLoaded&&!appsLoading)loadApps();}
