    private void updatePending(){if(appsPending==null)return;Set<String> draft=prefs.getStringSet("bypassApps",Collections.emptySet());Set<String> applied=prefs.getStringSet("activeBypassApps",Collections.emptySet());boolean dirty=vpn()&&!draft.equals(applied);appsPending.setText(dirty?"有未应用更改 · 已选 "+draft.size()+" 个":vpn()?"已应用 · "+prefs.getInt("activeBypassCount",0)+" 个应用放行":"已保存 "+draft.size()+" 个，开启后生效");appsPending.setTextColor(dirty?ERROR:MUTED);appsApply.setText(vpn()?"应用更改":"开启保护");}
