        gap(c,8);c.addView(text("加密模式使用标准解析服务，备用上游仍为 HTTPS。应用自带的加密 DNS 不会被此设置接管。",11,MUTED,false));addButton(c,"保存解析设置",true,()->{String ip=server.getText().toString().trim();if(!doh.isChecked())try{DnsVpnService.numericAddress(ip);}catch(Exception e){server.setError("请输入有效 DNS 数字 IP");return;}SharedPreferences.Editor edit=prefs.edit().putString("dnsTransport",doh.isChecked()?"doh":"udp").putString("dohProvider",provider.getSelectedItemPosition()==1?"google":"cloudflare");if(!doh.isChecked())edit.putString("upstream",ip);edit.apply();dialog.dismiss();if(vpn())restartVpn();else message("DNS 设置已保存，下次开启应用保护生效");});
